import { describe, test, expect } from 'bun:test';
import { hkdf } from './hkdf.js';
import { hmac } from './hmac.js';
import { sha256 } from './sha256.js';
import { bitArray } from '../utils/bitArray.js';
import { utf8 } from '../../io/codec/utf8.js';
import { hex } from '../../io/codec/hex.js';

const _ba = bitArray.factory();
const _utf8 = utf8.factory();
const _hex = hex.factory();
const _sha = sha256.factory(_ba, _utf8);
const _hmac = hmac.factory(_ba, _utf8, _sha);
const _hkdf = hkdf.factory(_ba, _utf8, _hmac);

const fromHex = (s) => Array.from(_ba.ui8_to_ba(_hex.toBytes(s)));
const toHex = (ba) => _hex.fromBytes(_ba.ba_to_ui8(ba));

describe('hkdf module (RFC 5869)', () => {

    test('module metadata', () => {
        expect(hkdf.name).toBe('hkdf');
        expect(hkdf.dependencies).toEqual(['bitArray', 'utf8', 'hmac']);
    });

    // RFC 5869 Appendix A.1 - Test Case 1 (Basic, SHA-256)
    describe('A.1 Test Case 1', () => {
        const ikm = fromHex('0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b');
        const salt = fromHex('000102030405060708090a0b0c');
        const info = fromHex('f0f1f2f3f4f5f6f7f8f9');
        const L = 42;
        const expectedPrk = '077709362c2e32df0ddc3f0dc47bba6390b6c73bb50f9c3122ec844ad7c2b3e5';
        const expectedOkm = '3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865';

        test('extract', () => {
            expect(toHex(_hkdf.extract(salt, ikm))).toBe(expectedPrk);
        });

        test('expand', () => {
            const prk = fromHex(expectedPrk);
            expect(toHex(_hkdf.expand(prk, info, L * 8))).toBe(expectedOkm);
        });

        test('derive (one-shot)', () => {
            expect(toHex(_hkdf.derive(salt, ikm, info, L * 8))).toBe(expectedOkm);
        });
    });

    // RFC 5869 Appendix A.2 - Test Case 2 (Longer inputs, SHA-256)
    describe('A.2 Test Case 2', () => {
        const ikm = fromHex(
            '000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f' +
            '202122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f' +
            '404142434445464748494a4b4c4d4e4f'
        );
        const salt = fromHex(
            '606162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f' +
            '808182838485868788898a8b8c8d8e8f909192939495969798999a9b9c9d9e9f' +
            'a0a1a2a3a4a5a6a7a8a9aaabacadaeaf'
        );
        const info = fromHex(
            'b0b1b2b3b4b5b6b7b8b9babbbcbdbebfc0c1c2c3c4c5c6c7c8c9cacbcccdcecf' +
            'd0d1d2d3d4d5d6d7d8d9dadbdcdddedfe0e1e2e3e4e5e6e7e8e9eaebecedeeef' +
            'f0f1f2f3f4f5f6f7f8f9fafbfcfdfeff'
        );
        const L = 82;
        const expectedPrk = '06a6b88c5853361a06104c9ceb35b45cef760014904671014a193f40c15fc244';
        const expectedOkm =
            'b11e398dc80327a1c8e7f78c596a49344f012eda2d4efad8a050cc4c19afa97c' +
            '59045a99cac7827271cb41c65e590e09da3275600c2f09b8367793a9aca3db71' +
            'cc30c58179ec3e87c14c01d5c1f3434f1d87';

        test('extract', () => {
            expect(toHex(_hkdf.extract(salt, ikm))).toBe(expectedPrk);
        });

        test('derive', () => {
            expect(toHex(_hkdf.derive(salt, ikm, info, L * 8))).toBe(expectedOkm);
        });
    });

    // RFC 5869 Appendix A.3 - Test Case 3 (zero-length salt and info, SHA-256)
    describe('A.3 Test Case 3', () => {
        const ikm = fromHex('0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b');
        const salt = [];
        const info = [];
        const L = 42;
        const expectedPrk = '19ef24a32c717b167f33a91d6f648bdf96596776afdb6377ac434c1c293ccb04';
        const expectedOkm = '8da4e775a563c18f715f802a063c5a31b8a11f5c5ee1879ec3454e5f3c738d2d9d201395faa4b61a96c8';

        test('extract with empty salt', () => {
            expect(toHex(_hkdf.extract(salt, ikm))).toBe(expectedPrk);
        });

        test('derive with empty salt and info', () => {
            expect(toHex(_hkdf.derive(salt, ikm, info, L * 8))).toBe(expectedOkm);
        });
    });

    describe('error handling', () => {
        test('rejects negative length', () => {
            expect(_hkdf.expand(fromHex('00'.repeat(32)), [], -1)).toBe(false);
        });

        test('rejects length > 255 * HashLen', () => {
            // 255 * 32 = 8160 bytes = 65280 bits ; one bit more triggers reject
            expect(_hkdf.expand(fromHex('00'.repeat(32)), [], 65281)).toBe(false);
        });
    });
});


// ============================================================================
// KDA-HKDF-Sp800-56Cr1 (NIST CAVP HKDF-as-KDA vectors)
// ----------------------------------------------------------------------------
// Source: references/NIST/ACVP-Server-1.1.0.42/gen-val/json-files/KDA-HKDF-Sp800-56Cr1/
// Coverage strategy:
//   - SP 800-56C §4.1 wraps RFC 5869 HKDF with a structured fixedInfo:
//       fixedInfo = uPartyInfo || vPartyInfo || L_be32
//       partyInfo = partyId || ephemeralData
//   - Cr1 has non-hybrid groups (Cr2 is all-hybrid) - use Cr1 directly.
//   - Filter: multiExpansion=false, usesHybridSharedSecret=false,
//     hmacAlg in {SHA-224, SHA-256, SHA-384, SHA-512} (4 HMAC variants
//     supported by hmac.js).
//   - AFT: 40 groups x 5 tests = 200 -> sub-sample 3/group => 120.
//   - VAL: 40 groups x 5 tests = 200 -> sub-sample 3/group => 120
//     (includes testPassed=false cases where the candidate dkm is corrupt).
//   - L=1024 bits, saltLen in {512, 1024} bits, zLength varies (224 to
//     65536 bits) -> exercises HKDF-Extract with very large IKM and Expand
//     with N=ceil(1024/HashLen) iterations.
//   - saltMethod 'default' -> salt is all-zeros of saltLen bits (already
//     filled in the vector). 'random' -> salt is a random byte string.
// ============================================================================

const _sha224 = (await import('./sha224.js')).sha224.factory(_sha);
const _sha512 = (await import('./sha512.js')).sha512.factory(_ba, _utf8);
const _sha384 = (await import('./sha384.js')).sha384.factory(_sha512);
const _sha512_224 = (await import('./sha512_224.js')).sha512_224.factory(_sha512);
const _sha512_256 = (await import('./sha512_256.js')).sha512_256.factory(_sha512);
const _sha3 = (await import('./sha3.js')).sha3.factory(_ba, _utf8);
const _hmac224 = hmac.factory(_ba, _utf8, _sha224);
const _hmac384 = hmac.factory(_ba, _utf8, _sha384);
const _hmac512 = hmac.factory(_ba, _utf8, _sha512);
const _hkdf224 = hkdf.factory(_ba, _utf8, _hmac224);
const _hkdf384 = hkdf.factory(_ba, _utf8, _hmac384);
const _hkdf512 = hkdf.factory(_ba, _utf8, _hmac512);

