const _hkdfByAlg = {
    'SHA2-224': _hkdf224,
    'SHA2-256': _hkdf,
    'SHA2-384': _hkdf384,
    'SHA2-512': _hkdf512,
};

describe('hkdf - KDA-HKDF-Sp800-56Cr1 (NIST CAVP, sub-sampled 3/group)', () => {

    describe('AFT (120 vectors / 400 -- HKDF-Extract+Expand byte-exact)', () => {
        test.each(HKDF_KDA_AFT)('tgId=$tg tcId=$tc ($alg, saltMethod=$sm, L=$l)', (v) => {
            const k = _hkdfByAlg[v.alg];
            const okm = k.derive(fromHex(v.salt), fromHex(v.z), fromHex(v.info), v.l);
            expect(toHex(okm)).toBe(v.dkm.toLowerCase());
        });
    });

    describe('VAL (120 vectors / 400 -- candidate dkm verify, includes pass+fail labels)', () => {
        test.each(HKDF_KDA_VAL)('tgId=$tg tcId=$tc ($alg, saltMethod=$sm, pass=$pass)', (v) => {
            const k = _hkdfByAlg[v.alg];
            const okm = k.derive(fromHex(v.salt), fromHex(v.z), fromHex(v.info), v.l);
            const match = (toHex(okm) === v.dkm.toLowerCase());
            expect(match).toBe(v.pass);
        });
    });

});


// ============================================================================
// HKDF - Iteration B3 of the FIPS 140-3 upgrade plan
// ----------------------------------------------------------------------------
// Extends HKDF coverage to the **10 HMAC families** now supported
// (4 SHA-2 + 2 SHA-512-truncated [A3] + 4 SHA-3 [A1]) and adds two modes
// from SP 800-56C Rev. 2 previously absent:
//   - hybrid shared secret (IKM = Z || T)
//   - multi-expansion (1 PRK → N expand iterations).
//
// Sources:
//   - KDA-HKDF-Sp800-56Cr1 : extension aux 6 nouvelles familles, AFT 3/group.
//   - KDA-HKDF-Sp800-56Cr2 : hybrid single-expansion AFT 2/group, capped 4/alg.
//   - KDA-HKDF-Sp800-56Cr2 : hybrid multi-expansion AFT 1/group, capped 2/alg.
// ============================================================================

const _hkdf512_224 = hkdf.factory(_ba, _utf8, hmac.factory(_ba, _utf8, _sha512_224));
const _hkdf512_256 = hkdf.factory(_ba, _utf8, hmac.factory(_ba, _utf8, _sha512_256));
const _hkdf3_224   = hkdf.factory(_ba, _utf8, hmac.factory(_ba, _utf8, _sha3.sha3_224_hash));
const _hkdf3_256   = hkdf.factory(_ba, _utf8, hmac.factory(_ba, _utf8, _sha3.sha3_256_hash));
const _hkdf3_384   = hkdf.factory(_ba, _utf8, hmac.factory(_ba, _utf8, _sha3.sha3_384_hash));
const _hkdf3_512   = hkdf.factory(_ba, _utf8, hmac.factory(_ba, _utf8, _sha3.sha3_512_hash));

const _hkdfByAlgB3 = {
    'SHA2-224':     _hkdf224,
    'SHA2-256':     _hkdf,
    'SHA2-384':     _hkdf384,
    'SHA2-512':     _hkdf512,
    'SHA2-512/224': _hkdf512_224,
    'SHA2-512/256': _hkdf512_256,
    'SHA3-224':     _hkdf3_224,
    'SHA3-256':     _hkdf3_256,
    'SHA3-384':     _hkdf3_384,
    'SHA3-512':     _hkdf3_512,
};

// Concatenate two hex strings into a single bitArray (used for hybrid IKM = Z || T).
const _concatHex = (a, b) => {
    const aBytes = _hex.toBytes(a);
    const bBytes = _hex.toBytes(b);
    const out = new Uint8Array(aBytes.length + bBytes.length);
    out.set(aBytes, 0);
    out.set(bBytes, aBytes.length);
    return _ba.ui8_to_ba(out);
};

