describe('hkdf - KDA-HKDF-Sp800-56Cr1 / extension 6 nouvelles familles HMAC (B3)', () => {
    test.each(HKDF_CR1_EXTRAS)('tgId=$tg tcId=$tc ($alg, saltMethod=$sm, L=$l)', (v) => {
        const k = _hkdfByAlgB3[v.alg];
        const okm = k.derive(fromHex(v.salt), fromHex(v.z), fromHex(v.info), v.l);
        expect(toHex(okm)).toBe(v.dkm.toLowerCase());
    });
});

describe('hkdf - KDA-HKDF-Sp800-56Cr2 / hybrid single-expansion AFT (B3)', () => {
    // Hybrid : IKM = Z || T (auxSharedSecret). Cf. SP 800-56C Rev. 2 §5.8.2.
    test.each(HKDF_CR2_SINGLE_HYBRID)('tgId=$tg tcId=$tc ($alg, hybrid Z||T, L=$l)', (v) => {
        const k = _hkdfByAlgB3[v.alg];
        const ikm = _concatHex(v.z, v.t);
        const okm = k.derive(fromHex(v.salt), ikm, fromHex(v.info), v.l);
        expect(toHex(okm)).toBe(v.dkm.toLowerCase());
    });
});

describe('hkdf - KDA-HKDF-Sp800-56Cr2 / hybrid multi-expansion AFT (B3)', () => {
    // Multi-expansion: a single (Z||T) extract, multiple `expand` with
    // distinct fixedInfo and l. Covers PRK reuse for independent
    // OKMs (TLS-style multi-key derivation).
    test.each(HKDF_CR2_MULTI_HYBRID)('tgId=$tg tcId=$tc ($alg, hybrid multi-expand, $iters.length iters)', (v) => {
        const k = _hkdfByAlgB3[v.alg];
        const ikm = _concatHex(v.z, v.t);
        const prk = k.extract(fromHex(v.salt), ikm);
        for (const it of v.iters) {
            const okm = k.expand(prk, fromHex(it.fixedInfo), it.l);
            expect(toHex(okm)).toBe(it.dkm.toLowerCase());
        }
    });
});
